package ingress

import (
	"strings"
	"testing"

	"github.com/open-linux-router/open-linux-router/internal/brandlogo"
)

// The catalogue is generated by the web build, and CI runs Go and Web in
// separate jobs, so a Go-only checkout has none. There is nothing to resolve
// then; the daemon reports it at startup instead.
func requireCatalogue(t *testing.T) {
	t.Helper()
	if !brandlogo.Built() {
		t.Skip("brand-logo catalogue not generated; run `make brand-logos` or `make web`")
	}
}

// The mark comes out of the binary now. This test fails if the bundle is empty,
// if the slug is spelled differently upstream, or if someone puts the network
// fetch back.
func TestCustomIconIsBundled(t *testing.T) {
	requireCatalogue(t)
	data, kind, err := CustomIcon("thesvg:caddy")
	if err != nil {
		t.Fatal(err)
	}
	if kind != "image/svg+xml" {
		t.Fatalf("kind = %q", kind)
	}
	if !strings.HasPrefix(strings.TrimSpace(string(data)), "<") || !strings.Contains(string(data), "<svg") {
		t.Fatalf("not a mark: %.60q", data)
	}
}

// A configuration may name a mark this build does not carry. That is an error
// at render time, not a validation failure — see ValidateCustomIcon.
func TestCustomIconRejectsAMarkItDoesNotCarry(t *testing.T) {
	requireCatalogue(t)
	if err := ValidateCustomIcon("thesvg:no-such-brand-at-all"); err != nil {
		t.Fatalf("validation rejected a well-formed slug: %v", err)
	}
	if _, _, err := CustomIcon("thesvg:no-such-brand-at-all"); err == nil {
		t.Fatal("resolved a mark that is not in the catalogue")
	}
}
